from pathlib import Path
from html import escape

ROOT = Path(__file__).parent
OFFICIAL = 'https://liberaalipuolue.fi'
PEOPLE = [
    ('lassi-kivinen', 'Lassi Kivinen', 'Puheenjohtaja', 'lassi'),
    ('laura-lahteenmaki', 'Laura Lähteenmäki', '1. varapuheenjohtaja', 'laura'),
    ('valtteri-turpeinen', 'Valtteri Turpeinen', '2. varapuheenjohtaja', 'valtteri'),
    ('nina-sneitz', 'Nina Sneitz', '3. varapuheenjohtaja', 'nina'),
    ('aarne-leinonen', 'Aarne Leinonen', 'Puoluesihteeri', 'aarne'),
]
NAV = [('tavoitteet.html','Tavoitteet'),('ihmiset.html','Ihmiset'),('keita-olemme.html','Keitä olemme'),('ajankohtaista.html','Ajankohtaista')]

def arrow(): return '<span aria-hidden="true">↗</span>'
def button(href, text, cls='primary'): return f'<a class="button {cls}" href="{href}">{text}<span aria-hidden="true">↗</span></a>'
def eyebrow(text): return f'<p class="eyebrow"><span></span>{text}</p>'
def source(href, name): return f'<p class="source">Lähde: <a href="{href}">{name} ↗</a></p>'
def note(text): return f'<aside class="editor-note"><strong>Sisältöluonnos</strong><p>{text}</p></aside>'
def crumb(label): return f'<div class="wrap breadcrumbs"><a href="index.html">Etusivu</a><span>/</span>{label}</div>'
def cta():
    return f'''<section class="join-band"><div class="wrap join-inner"><div>{eyebrow('Tule mukaan')}<h2>VAPAUS TARVITSEE<br>TEKIJÖITÄ.</h2><p>Oma tapasi osallistua voi olla pieni tai suuri.</p></div>{button('osallistu.html','Löydä oma tapasi','dark')}</div></section>'''
def shell(filename,title,body,section=None,description='Liberaalipuolueen verkkosivuston ulkoasuluonnos. Tutustu tavoitteisiin, ihmisiin ja puolueen taustaan.'):
    nav=''.join(f'<a href="{h}"'+(' aria-current="page"' if (section or filename)==h else '')+f'>{t}</a>' for h,t in NAV)
    footerlinks=''.join(f'<a href="{h}">{t}</a>' for h,t in NAV)
    html=f'''<!doctype html>
<html lang="fi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{escape(title)} · Liberaalipuolue · Mallisivusto</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#FFD500"><meta property="og:title" content="{escape(title)} — Liberaalipuolueen mallisivusto"><meta property="og:description" content="Verkkosivu-uudistuksen interaktiivinen HTML-luonnos."><link rel="icon" href="assets/logo.png" type="image/png"><link rel="preload" href="assets/raleway.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="assets/style.css"><script src="assets/main.js" defer></script></head>
<body><a class="skip" href="#sisalto">Siirry sisältöön</a><div class="prototype-bar"><div class="wrap"><span><b>MALLISIVUSTO</b> <span class="bar-detail">Verkkosivu-uudistuksen luonnos · 29.10.2026</span></span><a href="tietoa-mallista.html">Tietoa luonnoksesta ↗</a></div></div>
<header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Liberaalipuolue, etusivu"><img src="assets/logo.png" width="500" height="150" alt="Liberaalipuolue – vapaus valita"></a><button class="menu-button" aria-controls="navigation" aria-expanded="false">Valikko <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Päävalikko">{nav}<a href="osallistu.html" class="nav-join"{' aria-current="page"' if filename=='osallistu.html' else ''}>Tule mukaan <span aria-hidden="true">↗</span></a></nav></div></header>
<main id="sisalto">{body}</main>
<footer><div class="wrap footer-top"><div><a href="index.html"><img class="footer-logo" src="assets/logo-white.png" width="500" height="150" alt="Liberaalipuolue – vapaus valita"></a><p>Vapaus valita. Vastuu välittää.</p></div><div><h2>Tutustu</h2>{footerlinks}</div><div><h2>Osallistu</h2><a href="osallistu.html">Tule mukaan</a><a href="https://liberaalipuolue.fi/jaseneksi/">Hae jäseneksi ↗</a><a href="https://liberaalipuolue.fi/vaalit-2027/">Ehdokkaat 2027 ↗</a></div><div><h2>Ollaan yhteydessä</h2><a href="mailto:hallitus@liberaalipuolue.fi">hallitus@liberaalipuolue.fi</a><a href="https://liberaalipuolue.fi/">Puolueen nykyinen sivusto ↗</a><a href="tietoa-mallista.html">Lähteet ja tietoa mallista</a></div></div><div class="wrap footer-bottom"><span>Ulkoasuluonnos · Ei puolueen virallinen verkkosivusto</span><span>Oranssi. Keltainen. Vapaus.</span></div></footer></body></html>'''
    (ROOT/filename).write_text(html)

def person_card(p):
    slug,name,role,img=p
    return f'<a class="person-card" data-person="{name.lower()} {role.lower()}" href="{slug}.html"><div class="person-photo"><img loading="lazy" src="assets/{img}.webp" width="800" height="800" alt="{name}"><span class="circle-arrow" aria-hidden="true">↗</span></div><p>{role}</p><h3>{name}</h3></a>'

TOPICS=[
 ('verotus','01','Työ ja talous','Enemmän tilaa <br>työlle ja yrittämiselle.','Työn verotuksen keventäminen ja julkisten menojen priorisointi kuuluvat samaan kokonaisuuteen.','talous'),
 ('vapaus','02','Vapaus ja yhdenvertaisuus','Oma elämä. <br>Omat valinnat.','Samat oikeudet, yksityisyyden suoja ja vapaus elää omannäköistä elämää.','vapaus'),
 ('turva','03','Turva ja mahdollisuudet','Turvaa silloin, <br>kun sitä tarvitset.','Ymmärrettävä perusturva ja mahdollisuus rakentaa omaa tulevaisuutta.','turva'),
]
def topic_card(t):
    slug,num,label,title,desc,cat=t
    return f'<a class="topic-card" data-topic="{cat}" href="{slug}.html"><div class="topic-top"><span>{num} /</span>{arrow()}</div><p class="eyebrow">{label}</p><h3>{title}</h3><p>{desc}</p><span class="text-link">Mitä tämä tarkoittaa? →</span></a>'

home=f'''<section class="hero wrap"><div class="hero-copy">{eyebrow('Liberaalipuolue – vapaus valita')}<h1>VAPAUS<br>KUULUU<br><span>KAIKILLE.</span></h1><p class="lead">Enemmän tilaa elää omalla tavalla.<br>Vähemmän esteitä tehdä ja yrittää.</p><div class="actions">{button('tavoitteet.html','Tutustu tavoitteisiin')}{button('ihmiset.html','Tapaa ihmiset','text')}</div><div class="hero-note"><span class="small-check" aria-hidden="true">✓</span> Yksilönvapaus. Avoimuus. Vastuu.</div></div><div class="hero-visual"><div class="portrait-block main-portrait"><img src="assets/lassi.webp" width="800" height="800" alt="Puheenjohtaja Lassi Kivinen"><a class="portrait-caption" href="lassi-kivinen.html"><span><small>Puheenjohtaja</small><strong>Lassi Kivinen</strong></span>{arrow()}</a></div><div class="portrait-block side-portrait"><img src="assets/laura.webp" width="675" height="675" alt="Varapuheenjohtaja Laura Lähteenmäki"><a href="laura-lahteenmaki.html" class="side-caption">Laura Lähteenmäki {arrow()}</a></div><a href="ihmiset.html" class="yellow-tile"><span>AJATUSTEN<br>TAKANA ON<br>IHMISIÄ.</span>{arrow()}</a><div class="photo-credit">Kuvat: Liberaalipuolueen nykyinen kuvapankki</div></div></section>
<div class="principle-strip"><div class="wrap"><span>VAPAUS VALITA</span><span aria-hidden="true">✳</span><span>ROHKEUS UUDISTAA</span><span aria-hidden="true">✳</span><span>VASTUU VÄLITTÄÄ</span></div></div>
<section class="section wrap"><div class="section-heading"><div>{eyebrow('Mihin haluamme vaikuttaa')}<h2>VÄHEMMÄN ESTEITÄ.<br>ENEMMÄN MAHDOLLISUUKSIA.</h2></div><a href="tavoitteet.html" class="text-link">Kaikki tavoitteet ↗</a></div><div class="topic-grid">{''.join(topic_card(t) for t in TOPICS)}</div><p class="small muted">Teematekstit ovat toimituksellisia luonnoksia. Hyväksytyt linjaukset löytyvät puolueohjelmasta.</p></section>
<section class="about-band"><div class="wrap about-grid"><div>{eyebrow('Keitä me olemme')}<h2>VAPAUS EI OLE<br>VAIN ISKULAUSE.</h2></div><div><p class="lead">Se näkyy siinä, miten suhtaudumme toisiimme — ja siihen, mitä valta saa tehdä.</p><p>Liberaali ajattelu lähtee ihmisen oikeuksista ja omasta vastuusta. Yhteiskunnan on myös pidettävä huolta niistä, jotka tarvitsevat apua.</p><a class="text-link" href="keita-olemme.html">Tutustu arvoihin ja taustaan ↗</a></div></div></section>
<section class="section wrap"><div class="section-heading"><div>{eyebrow('Ihmiset puolueen takana')}<h2>TUTUSTU TEKIJÖIHIN.</h2></div><a href="ihmiset.html" class="text-link">Katso puoluejohto ↗</a></div><div class="people-grid home-people">{''.join(person_card(p) for p in PEOPLE[:4])}</div></section>
<section class="story-feature wrap"><div class="story-art" aria-hidden="true"><span>OMA<br>ÄÄNI.</span><div class="speech-mark">”</div></div><div class="story-copy">{eyebrow('Jäsenten tarinat')}<h2>MIKÄ SAI SINUT<br>LÄHTEMÄÄN MUKAAN?</h2><p>Politiikka saa merkityksensä ihmisten arjesta. Tähän osioon tuodaan jäsenten omat kokemukset, kysymykset ja syyt toimia.</p><p class="small muted">Haastattelusarjan esimerkkirakenne. Oikeat tarinat julkaistaan haastattelujen jälkeen.</p>{button('tarinat.html','Tutustu tarinaosioon','outline')}</div></section>
<section class="section wrap"><div class="section-heading"><div>{eyebrow('Tutustu tarkemmin')}<h2>AJATUKSISTA TEKOIHIN.</h2></div><a href="ajankohtaista.html" class="text-link">Lisää ajankohtaista ↗</a></div><div class="news-grid"><a class="news-item" href="https://liberaalipuolue.fi/vaalit-2027/"><span class="tag">Eduskuntavaalit 2027</span><h3>Tutustu ehdokkaisiin ja ehdolle hakemiseen.</h3><span class="text-link">Puolueen vaalisivulle ↗</span></a><a class="news-item" href="verotus.html"><span class="tag">Talous · teemaluonnos</span><h3>Miten verotuksen keventäminen rahoitetaan?</h3><span class="text-link">Lue perustelurakenne ↗</span></a><a class="news-item" href="https://liberaalipuolue.fi/puolueohjelma/"><span class="tag">Puolueohjelma</span><h3>Arvot, tavoitteet ja niiden yksityiskohdat.</h3><span class="text-link">Lue hyväksytty ohjelma ↗</span></a></div></section>{cta()}'''
shell('index.html','Vapaus kuuluu kaikille',home)
# A memorable alias for the requested homepage HTML.
(ROOT/'liberaali-etusivu.html').write_text((ROOT/'index.html').read_text())

shell('tavoitteet.html','Tavoitteet',crumb('Tavoitteet')+f'''<section class="wrap page-intro">{eyebrow('Tavoitteet')}<h1>ISO AJATUS.<br><span>KONKREETTISET KEINOT.</span></h1><p class="lead">Aloita teemasta, joka kiinnostaa. Näet samalla, mitä muutosta tavoitellaan ja mitä kysymyksiä toteutuksessa on ratkaistava.</p></section><section class="wrap section compact"><div class="filter-bar" role="group" aria-label="Rajaa tavoitteita"><button aria-pressed="true" data-filter="all">Kaikki teemat</button><button aria-pressed="false" data-filter="talous">Työ ja talous</button><button aria-pressed="false" data-filter="vapaus">Vapaus</button><button aria-pressed="false" data-filter="turva">Turva</button></div><p class="sr-only" id="filter-status" aria-live="polite"></p><div class="topic-grid">{''.join(topic_card(t) for t in TOPICS)}</div>{note('Tiivistelmät havainnollistavat uuden sivuston esitystapaa. Ne eivät korvaa hyväksyttyä puolueohjelmaa.')}{button('https://liberaalipuolue.fi/puolueohjelma/','Lue koko puolueohjelma','outline')}</section>{cta()}''')

POLICIES=[
 ('verotus','Työ ja talous','TYÖSTÄ PITÄÄ<br>JÄÄDÄ ENEMMÄN.','Verotuksen keventäminen tarvitsee rinnalleen uskottavan suunnitelman julkisista menoista.',
 'Työnteon kannusteet ja julkisen talouden kestävyys on tarkasteltava yhdessä.',
 [('Tavoite','Työn verotuksen keventäminen ja verojärjestelmän selkeyttäminen.'),('Keino','Menojen priorisointi sekä tukien ja tehtävien arviointi.'),('Reunaehto','Rahoitus, vaikutukset ja siirtymä on avattava ennen päätöksiä.')],
 [('Mikä muuttuisi arjessa?','Toteutus vaikuttaisi eri kotitalouksiin eri tavoin. Nettovaikutus riippuu verojen lisäksi etuuksista, palveluista ja kulutuksen hinnoista. Yksittäistä euromääräistä hyötyä ei voi luvata ilman laskelmaa.'),('Mistä rahat tulevat?','Jokaiselle veromuutokselle tarvitaan näkyvä rahoitusvastine. Pysyviä kevennyksiä ei pidä perustella pelkillä kertatuloilla tai varmoiksi oletetuilla kasvuhyödyillä.'),('Entä palvelut ja pienituloiset?','Menomuutosten yhteydessä on eriteltävä, keiden palveluihin tai toimeentuloon muutos osuu ja millainen siirtymäaika tarvitaan.'),('Miten tämä sivu viimeistellään?','Julkaistavaan versioon lisätään hyväksytty ehdotus, laskelmien lähtöoletukset, rahoitustaulukko sekä kotitalous- ja palveluvaikutukset. Tämä sivu havainnollistaa perustelujen rakennetta.')]),
 ('vapaus','Vapaus ja yhdenvertaisuus','OMA ELÄMÄ.<br>OMAT VALINNAT.','Vapauteen kuuluu myös toisten ihmisten vastaavien oikeuksien kunnioittaminen.',
 'Sääntelyn tarpeellisuus on voitava perustella. Yksityisyys ja yhdenvertaisuus kuuluvat kaikille.',
 [('Tavoite','Yhtäläiset oikeudet ja vahva yksityisyyden suoja.'),('Keino','Tarpeettomien rajoitusten arviointi ja purkaminen.'),('Reunaehto','Muille aiheutuvat haitat ja turvallisuus huomioidaan.')],
 [('Mitä vapaus tarkoittaa käytännössä?','Mahdollisuutta tehdä omaa elämää koskevia valintoja ja saada yhdenvertainen kohtelu. Yksilönvapautta arvioidaan yhdessä muiden oikeuksien kanssa.'),('Voiko kaikki sääntely poistua?','Sääntelyä tarvitaan esimerkiksi oikeuksien ja turvallisuuden turvaamiseen. Jokaisesta muutoksesta pitäisi kertoa, mitä velvoitetta puretaan ja miten sen alkuperäinen tarkoitus turvataan.'),('Miksi yksityisyys on tärkeä?','Omaa elämää koskevien tietojen hallinta on osa vapautta. Valvontaa ja tietojen keräämistä pitää voida arvioida avoimesti.'),('Mistä löydän tarkat linjaukset?','Hyväksytyt tavoitteet ja niiden rajaukset ovat puolueohjelman Vapaus-luvussa. Tämän mallisivun tekstit ovat tiivistävä sisältöluonnos.')]),
 ('turva','Turva ja mahdollisuudet','TURVAA.<br>ILMAN TURHIA ESTEITÄ.','Ymmärrettävä järjestelmä auttaa silloin, kun elämä ei mene suunnitelmien mukaan.',
 'Toimeentulon turvan pitää olla ymmärrettävä, ja avun tulee tavoittaa sitä tarvitsevat.',
 [('Tavoite','Selkeämpi perusturva ja mahdollisuus päästä eteenpäin.'),('Keino','Etuuksien ja työn yhteensovittamisen uudistaminen.'),('Reunaehto','Riittävyys ja erilaisten elämäntilanteiden vaikutukset arvioidaan.')],
 [('Mikä ongelma pitäisi ratkaista?','Ihmisen on voitava ymmärtää, miten työ, etuudet ja elämäntilanteen muutokset vaikuttavat toimeentuloon.'),('Mitä tapahtuu siirtymävaiheessa?','Uudistuksesta tarvitaan selkeä aikataulu. Ihmiselle pitää kertoa etukäteen, miten oma tilanne muuttuu ja mistä saa apua.'),('Miten vaikutuksia seurataan?','Julkaistavaan suunnitelmaan kuuluvat toimeentulon riittävyyttä, palvelujen saatavuutta ja työn vastaanottamista kuvaavat mittarit. Mallissa ei esitetä vielä laskemattomia tuloksia.'),('Mikä on puolueen hyväksytty linja?','Sosiaaliturvan tavoitteet löytyvät puolueohjelmasta. Tämä sivu näyttää, miten tavoite voidaan esitellä lukijalle vaiheittain.')]),
]
for slug,label,title,intro,problem,steps,faqs in POLICIES:
    body=crumb(f'<a href="tavoitteet.html">Tavoitteet</a> / {label}')+f'''<section class="wrap policy-hero"><div>{eyebrow(label)}<h1>{title}</h1><p class="lead">{intro}</p><a class="text-link" href="#perustelut">Lue perustelut ↓</a></div><div class="policy-number"><span>VAPAUS<br>VALITA.</span><strong>{'01' if slug=='verotus' else '02' if slug=='vapaus' else '03'}</strong><small>Teematekstin luonnos</small></div></section><section class="section wrap" id="perustelut"><div class="article-grid"><aside class="article-aside">{eyebrow('Miksi tämä muutos?')}<p>{problem}</p><a href="https://liberaalipuolue.fi/puolueohjelma/">Hyväksytty puolueohjelma ↗</a></aside><div><h2>TAVOITE, KEINOT<br>JA VAIKUTUKSET.</h2><div class="steps">{''.join(f'<div><span>0{i+1}</span><section><h3>{a}</h3><p>{b}</p></section></div>' for i,(a,b) in enumerate(steps))}</div><h2 class="faq-heading">HYVÄT KYSYMYKSET<br>ANSAITSEVAT VASTAUKSEN.</h2><div class="accordions">{''.join(f'<details'+(' open' if i==0 else '')+f'><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for i,(q,a) in enumerate(faqs))}</div>{note('Tämä on ehdotus politiikan perustelujen esitystavaksi. Tarkat muutokset, laskelmat ja vaikutusarviot hyväksytään erikseen ennen virallista julkaisua.')}{source('https://liberaalipuolue.fi/puolueohjelma/','Puolueohjelma, hyväksytty 14.6.2026')}</div></div></section>{cta()}'''
    shell(slug+'.html',label,body,'tavoitteet.html')

shell('ihmiset.html','Ihmiset',crumb('Ihmiset')+f'''<section class="wrap page-intro">{eyebrow('Ihmiset')}<h1>AJATUKSET TARVITSEVAT<br><span>TEKIJÄNSÄ.</span></h1><p class="lead">Tutustu puolueen johtoon. Henkilökorteista avautuvat omat esittelysivut ja yhteydenottopolut.</p></section><section class="section compact wrap"><div class="people-toolbar"><h2>PUOLUEJOHTO</h2><div class="search-field"><label for="people-search">Etsi nimellä tai tehtävällä</label><input type="search" id="people-search" placeholder="Esim. Laura tai puheenjohtaja" autocomplete="off"></div></div><p id="people-status" class="small muted" aria-live="polite">5 henkilöä</p><div class="people-grid">{''.join(person_card(p) for p in PEOPLE)}</div><p class="empty-message" hidden>Haulla ei löytynyt henkilöitä. Kokeile toista nimeä tai tehtävää.</p>{source('https://liberaalipuolue.fi/puoluehallitus/','Puoluehallitus; tiedot tarkistettu 29.10.2026')}<p class="small muted">Malli käyttää nykyisiä virallisia kuvia. Uusi henkilökuvaus ja toimitetut haastattelut täydentävät julkaistavaa versiota.</p></section><section class="wrap mini-banner"><h2>ENTÄ OMAN ALUEESI EHDOKKAAT?</h2>{button('https://liberaalipuolue.fi/vaalit-2027/','Tutustu ehdokkaisiin','outline')}</section>{cta()}''')

for slug,name,role,img in PEOPLE:
    others=[p for p in PEOPLE if p[0]!=slug][:3]
    shell(slug+'.html',name,crumb(f'<a href="ihmiset.html">Ihmiset</a> / {name}')+f'''<section class="wrap profile-hero"><div class="profile-photo"><img src="assets/{img}.webp" width="800" height="800" alt="{name}"></div><div>{eyebrow(role)}<h1>{name.upper().replace(' ','<br>',1)}</h1><p class="lead">Liberaalipuolueen {role.lower()}.</p><p>Puolueen johtoon voi olla yhteydessä myös yhteisen hallitusosoitteen kautta.</p>{button('mailto:hallitus@liberaalipuolue.fi','Ota yhteyttä','primary')}{source('https://liberaalipuolue.fi/puoluehallitus/','Puolueen virallinen hallitussivu')}</div></section><section class="section wrap"><div class="article-grid"><aside class="article-aside">{eyebrow('Esittelysivun sisältö')}<p>Tehtävä ja kuva ovat puolueen nykyiseltä verkkosivulta.</p></aside><div><h2>OMA ÄÄNI.<br>OMA SYY TOIMIA.</h2><p class="lead">Henkilöesittelyssä kerrotaan, kuka ihminen tehtävän takana on.</p><p>Julkaistavaan versioon toimitetaan henkilön hyväksymä haastattelu, oma tausta sekä hänelle tärkeät teemat. Sitaatteja tai henkilökohtaisia kokemuksia ei ole keksitty mallia varten.</p><div class="question-list"><p><span>01</span> Miksi lähdit mukaan?</p><p><span>02</span> Mitä haluat muuttaa?</p><p><span>03</span> Mistä sinut tuntee politiikan ulkopuolella?</p></div>{button('tarinat.html','Katso haastattelun rakenne','outline')}</div></div></section><section class="wrap section compact"><h2>TUTUSTU MYÖS</h2><div class="people-grid three">{''.join(person_card(p) for p in others)}</div></section>{cta()}''','ihmiset.html')

shell('keita-olemme.html','Keitä olemme',crumb('Keitä olemme')+f'''<section class="wrap page-intro">{eyebrow('Keitä olemme')}<h1>VAPAUS VALITA.<br><span>VASTUU VÄLITTÄÄ.</span></h1><p class="lead">Liberaalipuolueen ajattelun ytimessä ovat yksilönvapaus, yhdenvertaisuus ja avoin päätöksenteko.</p></section><section class="about-band"><div class="wrap about-grid"><h2>IHMINEN ENSIN.<br>VALTA VASTUUSEEN.</h2><div><p class="lead">Oma elämä kuuluu ihmiselle itselleen. Yhteiset päätökset kuuluvat avoimeen keskusteluun.</p><p>Puolueen yleisohjelma yhdistää vapauden, vastuun ja heikommassa asemassa olevista huolehtimisen. Siinä korostetaan myös tietoa ja perustelujen avoimuutta.</p>{source('https://liberaalipuolue.fi/yleisohjelma/','Yleisohjelma')}</div></div></section><section class="section wrap"><div class="section-heading"><div>{eyebrow('Aate ja organisaatio')}<h2>PITKÄ AATE.<br>OMA HISTORIA.</h2></div></div><div class="article-grid"><aside class="article-aside"><p>Liberaalin aatteen historia ja nykyisen puolueen historia ovat eri asioita.</p></aside><div><div class="timeline"><article><span>1965</span><div><h3>Liberaalinen kansanpuolue</h3><p>Suomen aiempaan liberaaliin puoluehistoriaan kuuluu vuonna 1965 muodostettu LKP. Nykyistä Liberaalipuoluetta ei tässä esitetä sen organisatorisena jatkajana.</p><a class="source" href="https://www.mtvuutiset.fi/artikkeli/viskipuolue-vaihtaa-nimensa-liberaalipuolueeksi/5896382">Lähde: MTV / STT, 16.5.2016 ↗</a></div></article><article><span>2016</span><div><h3>Nykyinen nimi</h3><p>Kansallinen Viskipuolue vaihtoi nimekseen Liberaalipuolue – Vapaus valita. Tausta kerrotaan avoimesti; nykyiset tavoitteet avataan koko ohjelman kautta.</p><a class="source" href="https://yle.fi/a/3-8978656">Lähde: Yle, 22.6.2016 ↗</a></div></article><article><span>2026</span><div><h3>Hyväksytty puolueohjelma</h3><p>Vuosikokouksessa 14.6.2026 hyväksytty ohjelma kertoo puolueen tämänhetkisistä tavoitteista.</p><a class="source" href="https://liberaalipuolue.fi/puolueohjelma/">Lue puolueohjelma ↗</a></div></article></div>{note('Aikajana on rajattu, lähteistetty luonnos. Laajempi katsaus liberalismiin Suomen parlamentarismissa toimitetaan ja tarkistetaan erikseen.')}</div></div></section><section class="wrap mini-banner"><div><h2>HALUATKO TIETÄÄ ENEMMÄN?</h2><p>Tavoitteet ja ihmiset kertovat, mihin olemme menossa.</p></div>{button('tavoitteet.html','Tutustu tavoitteisiin','outline')}</section>{cta()}''')

shell('tarinat.html','Jäsenten tarinat',crumb('Jäsenten tarinat')+f'''<section class="wrap page-intro">{eyebrow('Jäsenten tarinat · osion luonnos')}<h1>JOKAISELLA ON<br><span>OMA SYYNSÄ.</span></h1><p class="lead">Yksi haluaa vaikuttaa lähiympäristöönsä. Toinen kysyä, voisiko asian tehdä järkevämmin. Tässä on paikka ihmisten omille kertomuksille.</p></section><section class="story-feature wrap"><div class="story-art" aria-hidden="true"><span>MINUN<br>SYYNI.</span><div class="speech-mark">”</div></div><div class="story-copy">{eyebrow('Haastattelusarjan malli')}<h2>MIKSI LÄHDIN<br>MUKAAN?</h2><p>Tarinan keskiössä on haastateltavan arki, oma havainto ja hetki, jolloin hän päätti toimia.</p><p class="small muted">Tässä luonnoksessa ei ole julkaistu keksittyä jäsenkertomusta tai sitaattia.</p>{button('tarina.html','Avaa tarinan sivupohja','outline')}</div></section><section class="section wrap"><h2>ENSIN IHMINEN.<br>SITTEN POLITIIKKA.</h2><div class="news-grid"><div class="news-item"><span class="tag">01 · Arki</span><h3>Mistä oma kiinnostus syntyi?</h3><p>Haastateltavan kokemus omilla sanoilla.</p></div><div class="news-item"><span class="tag">02 · Valinta</span><h3>Miksi juuri tämä puolue?</h3><p>Motivaatio ja myös avoimet kysymykset.</p></div><div class="news-item"><span class="tag">03 · Toiminta</span><h3>Mitä mukaan lähteminen muutti?</h3><p>Konkreettinen kuva osallistumisesta.</p></div></div></section>{cta()}''','ihmiset.html')
shell('tarina.html','Miksi lähdin mukaan – tarinapohja',crumb('<a href="tarinat.html">Jäsenten tarinat</a> / Tarinapohja')+f'''<article class="wrap article-narrow section compact">{eyebrow('Haastattelun sivupohja · ei julkaistu henkilötarina')}<h1>MIKSI LÄHDIN<br><span>MUKAAN?</span></h1><p class="lead">Tässä lopullisen haastattelun ingressi kertoo, kuka ihminen on ja mikä sai hänet toimimaan.</p><div class="interview-image"><span>OMA TARINA.<br>OMASSA YMPÄRISTÖSSÄ.</span><p>Paikka haastattelussa otettavalle aidolle ympäristökuvalle.</p></div><h2>Kaikki alkoi yhdestä kysymyksestä.</h2><p>Ensimmäisessä osassa avataan henkilön arkea ja konkreettista kokemusta. Haastateltava kertoo itse, mikä tuntui tärkeältä ja mitä hän halusi ymmärtää paremmin.</p><h2>Mukaan omalla tavalla.</h2><p>Toisessa osassa kuvataan ensimmäinen askel toimintaan: keskustelu, tapahtuma tai oma aloite. Myös epäilyt ja keskeneräiset ajatukset kuuluvat aitoon tarinaan.</p><h2>Mitä toivon seuraavaksi?</h2><p>Lopussa katse siirtyy tulevaisuuteen. Henkilön kokemus yhdistetään yhteen tarkemmin perusteltuun teemaan.</p>{note('Tämä on toimituksellinen rakenne, ei oikean jäsenen kertomus. Nimi, valokuva ja henkilön hyväksymä haastattelu lisätään ennen varsinaista julkaisua.')}{button('tarinat.html','Takaisin tarinaosioon','outline')}</article>{cta()}''','ihmiset.html')

shell('osallistu.html','Tule mukaan',crumb('Tule mukaan')+f'''<section class="wrap page-intro">{eyebrow('Osallistu')}<h1>MUUTOS TARVITSEE<br><span>MYÖS SINUA.</span></h1><p class="lead">Voit tutustua, kysyä tai lähteä toimimaan. Valitse itsellesi sopiva seuraava askel.</p></section><section class="section compact wrap"><div class="participation-grid"><article class="participation featured"><span class="step-number">01</span><h2>LIITY<br>JÄSENEKSI.</h2><p>Jäsenyyttä haetaan puolueen virallisen sivuston kautta. Sieltä löytyvät ajantasaiset ehdot ja jäsenmaksut.</p>{button('https://liberaalipuolue.fi/jaseneksi/','Avaa jäsenyyssivu','dark')}</article><article class="participation"><span class="step-number">02</span><h2>TUTUSTU<br>TEKIJÖIHIN.</h2><p>Kysy toiminnasta tai ota yhteyttä puoluejohtoon. Myös omat kysymykset ja kehitysehdotukset ovat hyvä alku.</p>{button('ihmiset.html','Tapaa ihmiset','outline')}</article><article class="participation"><span class="step-number">03</span><h2>LÄHDE<br>EHDOLLE.</h2><p>Tutustu vuoden 2027 eduskuntavaalien ehdokkaisiin ja ehdolle hakemiseen puolueen vaalisivulla.</p>{button('https://liberaalipuolue.fi/vaalit-2027/','Avaa vaalisivu','outline')}</article></div><div class="contact-block"><div>{eyebrow('Aloita keskustelusta')}<h2>MIKÄ SINUA MIETITYTTÄÄ?</h2></div><a class="big-contact" href="mailto:hallitus@liberaalipuolue.fi">Kirjoita meille ↗</a></div><p class="small muted">Mallisivusto ei kerää jäsenhakemuksia tai henkilötietoja. Jäseneksi hakeminen tapahtuu puolueen virallisella sivustolla.</p></section>''')

shell('ajankohtaista.html','Ajankohtaista',crumb('Ajankohtaista')+f'''<section class="wrap page-intro">{eyebrow('Ajankohtaista')}<h1>TUTUSTU.<br><span>KYSY. OTA SELVÄÄ.</span></h1><p class="lead">Politiikan taustat, ihmiset ja seuraavat askeleet.</p></section><section class="section compact wrap"><div class="news-grid"><a class="news-item" href="https://liberaalipuolue.fi/vaalit-2027/"><span class="tag">Virallinen vaalisivu</span><h3>Eduskuntavaalit 2027</h3><p>Ehdokkaat ja ohjeet ehdolle hakemisesta.</p><span class="text-link">Avaa vaalisivu ↗</span></a><a class="news-item" href="https://liberaalipuolue.fi/puolueohjelma/"><span class="tag">Hyväksytty 14.6.2026</span><h3>Puolueohjelma</h3><p>Tutustu hyväksyttyihin tavoitteisiin kokonaisuudessaan.</p><span class="text-link">Lue ohjelma ↗</span></a><a class="news-item" href="tarinat.html"><span class="tag">Tulevan sarjan luonnos</span><h3>Oma syy toimia</h3><p>Katso, miten jäsenten omat kertomukset tuodaan osaksi sivustoa.</p><span class="text-link">Tutustu sivupohjaan ↗</span></a></div><div class="event-empty">{eyebrow('Tapahtumat')}<h2>NÄHDÄÄN KASVOTUSTEN.</h2><p>Tulevaan sivustoon tapahtumat tuodaan yhteisestä kalenterista. Tähän malliin ei ole lisätty keksittyjä tapahtumia.</p>{button('https://liberaalipuolue.fi/','Tarkista nykyisen sivuston tapahtumat','outline')}</div></section>{cta()}''')

shell('tietoa-mallista.html','Tietoa luonnoksesta',crumb('Tietoa luonnoksesta')+f'''<section class="wrap article-narrow section compact">{eyebrow('Verkkosivu-uudistus · 29.10.2026')}<h1>ILME, JOKA<br><span>PALVELEE SISÄLTÖÄ.</span></h1><p class="lead">Tämä on interaktiivinen HTML-malli Liberaalipuolueen uudeksi verkkosivustoksi. Se ei ole puolueen virallinen sivusto.</p><h2>Mitä mallissa voi kokeilla?</h2><p>Etusivu, tavoitteet ja kolme teemasivua, henkilölista hakuineen ja viisi henkilöesittelyä, puolueen tausta, henkilötarinoiden rakenne, ajankohtaista sekä osallistumisen polut. Valikot, teemasuodatus, henkilöhaku ja kysymysten avaukset toimivat.</p><h2>Graafinen perusta</h2><p>Vuoden 2017 graafinen manuaali: Raleway Regular ja Bold, isot pääotsikot, reilu tila ja viralliset logot muuttamattomina. Mediakirjaston verkkovärit: oranssi #F9B000 ja keltainen #FFD500. Tumma teksti varmistaa luettavuuden väripinnoilla.</p><div class="swatches"><span style="background:#F9B000">#F9B000</span><span style="background:#FFD500">#FFD500</span><span style="background:#202020;color:white">#202020</span></div><h2>Sisältöjen tila</h2><p>Politiikkatekstit ovat toimituksellisia luonnoksia. Ne eivät ole uusia hyväksyttyjä linjauksia tai vaikutusarvioita. Henkilöiden nimet, tehtävät ja kuvat ovat viralliselta sivulta, tarkistettu 29.10.2026. Henkilökohtaisia tarinoita, sitaatteja tai uusia ammattikuvia ei ole keksitty.</p><p>Ennen varsinaisen sivuston käyttöönottoa tarvitaan sisältöjen hyväksyntä, uusi henkilökuvaus, aidot haastattelut, laajempi historiakatsaus sekä suomen-, ruotsin- ja englanninkieliset sisällöt.</p><h2>Lähteet ja aineistot</h2><ul class="source-list"><li><a href="https://liberaalipuolue.fi/wp-content/uploads/2017/11/Liberaalipuolue_Graafinen_Manuaali.pdf">Graafinen manuaali (PDF) ↗</a></li><li><a href="https://liberaalipuolue.fi/media/">Viralliset logot ja verkkovärit ↗</a></li><li><a href="https://liberaalipuolue.fi/puoluehallitus/">Henkilöt, tehtävät ja valokuvat ↗</a></li><li><a href="https://liberaalipuolue.fi/puolueohjelma/">Puolueohjelma 2026 ↗</a></li><li><a href="https://liberaalipuolue.fi/yleisohjelma/">Yleisohjelma ↗</a></li><li><a href="https://yle.fi/a/3-8978656">Nykyisen puolueen nimenmuutos, Yle 22.6.2016 ↗</a></li><li><a href="https://www.mtvuutiset.fi/artikkeli/viskipuolue-vaihtaa-nimensa-liberaalipuolueeksi/5896382">Aiempaa puoluehistoriaa, MTV / STT 16.5.2016 ↗</a></li><li><a href="assets/font-license.txt">Raleway-kirjasimen OFL-lisenssi</a></li></ul><h2>Tekniikka ja yksityisyys</h2><p>Valmiit HTML-sivut, yhteinen CSS ja pieni JavaScript-tiedosto. Fontti ja kuvat ladataan samalta palvelimelta. Ei analytiikkaa, evästeitä, lomakkeita tai ulkopuolisia upotuksia. Sivuston julkaisualusta voi käsitellä tavanomaisia palvelinlokeja.</p><p>Mallisivuilla on hakukoneindeksoinnin estävä metatieto ja robots.txt. Nämä eivät ole pääsynrajoitus: GitHub Pages -julkaisu on julkinen.</p>{button('index.html','Takaisin etusivulle','outline')}</section>''')
(ROOT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(ROOT/'.nojekyll').write_text('')
print('Generated',len(list(ROOT.glob('*.html'))),'HTML pages')
